    def __post_init__(self):
        if self.weapon is None:
            self.weapon = Weapon(WeaponType.RANGED, 25, 1.0, 30)

    def take_damage(self, damage: float) -> float:
        actual_damage = damage * (1 - min(self.armor / 100, 0.75))  # armor reduces damage up to 75%
        self.health -= actual_damage
        if self.health <= 0:
            self.health = 0
            self.is_alive = False
        return actual_damage

    def heal(self, amount: float):
        self.health = min(self.health + amount, self.max_health)

    def add_power_up(self, power_up_type: PowerUpType, duration: float):
        self.power_ups[power_up_type] = duration

    def update_power_ups(self, delta_time: float):
        to_remove = []
        for power_up, duration in self.power_ups.items():
            self.power_ups[power_up] = duration - delta_time
            if self.power_ups[power_up] <= 0:
                to_remove.append(power_up)

        for power_up in to_remove:
            del self.power_ups[power_up]
            # Apply power-up removal effects
            if power_up == PowerUpType.SPEED_BOOST:
                self.movement_speed = max(2.0, self.movement_speed * 0.8)  # revert speed boost
            elif power_up == PowerUpType.DAMAGE_BOOST:
                self.weapon.damage = self.weapon.base_damage  # revert damage boost
            elif power_up == PowerUpType.SHIELD:
                self.armor = 0.0  # remove shield

    def can_use_weapon(self) -> bool:
        if "weapon" not in self.cooldowns:
            return True
        return self.cooldowns["weapon"] <= 0

    def use_weapon(self) -> bool:
        if self.can_use_weapon():
            self.cooldowns["weapon"] = self.weapon.cooldown
            return True
        return False

    def update_cooldowns(self, delta_time: float):
        for key in list(self.cooldowns.keys()):
            self.cooldowns[key] = max(0, self.cooldowns[key] - delta_time)

    def get_status(self) -> Dict[str, Any]:
        return {
            "id": self.id,
            "team": self.team.name,
            "health": self.health,
            "role": self.role.value,
            "alive": self.is_alive,
            "position": (self.position.x, self.position.y),
            "power_ups": [p.value for p in self.power_ups.keys()],
            "weapon": self.weapon.type.value,
            "objective_progress": self.capture_progress
        }

