            if power_up == PowerUpType.SPEED_BOOST:
                self.movement_speed = max(2.0, self.movement_speed * 0.8)  # revert speed boost
            elif power_up == PowerUpType.DAMAGE_BOOST:
                self.weapon.damage = self.weapon.base_damage  # revert damage boost
            elif power_up == PowerUpType.SHIELD:
                self.armor = 0.0  # remove shield

    def can_use_weapon(self) -> bool:
        if "weapon" not in self.cooldowns:
            return True
        return self.cooldowns["weapon"] <= 0

    def use_weapon(self) -> bool:
        if self.can_use_weapon():
            self.cooldowns["weapon"] = self.weapon.cooldown
            return True
        return False

    def update_cooldowns(self, delta_time: float):
        for key in list(self.cooldowns.keys()):
            self.cooldowns[key] = max(0, self.cooldowns[key] - delta_time)

    def get_status(self) -> Dict[str, Any]:
        return {
            "id": self.id,
            "team": self.team.name,
            "health": self.health,
            "role": self.role.value,
            "alive": self.is_alive,
            "position": (self.position.x, self.position.y),
            "power_ups": [p.value for p in self.power_ups.keys()],
            "weapon": self.weapon.type.value,
            "objective_progress": self.capture_progress
        }

@dataclass
class Weapon:
    type: WeaponType
    damage: float
    cooldown: float
    range: float
    base_damage: float = field(init=False)

    def __post_init__(self):
        self.base_damage = self.damage

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2
    team: Optional[Team] = None  # Which team currently controls it
    capture_radius: float = 50.0
    capture_time: float = 10.0  # seconds to capture
    is_active: bool = True
    progress: float = 0.0  # 0-1 for capture progress
    team_control: Optional[Team] = None
    last_capture_time: float = 0.0
    defenders: List[int] = field(default_factory=list)  # robot IDs defending this objective

    def update_capture(self, robot_id: int, team: Team, delta_time: float) -> float:
        """Update capture progress if robot is in range"""
        if self.team_control == team:
            # Already controlled by same team - regenerate progress
            self.progress = min(1.0, self.progress + delta_time / 5.0)  # 5 seconds to fully recapture
            return self.progress

        # Check if robot is in capture radius
        # This is simplified - in reality we'd check distance from robot to objective
        if self.progress < 1.0:
            self.progress += delta_time / self.capture_time
            if self.progress >= 1.0:
                self.team_control = team
                self.last_capture_time = time.time()
                self.progress = 1.0
                # Reset other team's capture progress
                self.team_control = team
        return self.progress

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2
    duration: float = 15.0  # duration in seconds
    spawn_time: float = 0.0
    is_active: bool = True
    radius: float = 30.0

    def is_collected_by(self, robot: Robot) -> bool:
        return self.position.distance_to(robot.position) <= self.radius

@dataclass
class Hazard:
    type: HazardType
    position: Vector2
    radius: float
    damage_per_second: float
    active: bool = True
    spawn_time: float = 0.0

@dataclass
class GameState:
    time: float = 0.0
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    round_start_time: float = 0.0
    round_duration: float = 300.0  # 5 minutes
    current_objective: ObjectiveType = ObjectiveType.FLAG_CAPTURE
    is_round_active: bool = False
    winner: Optional[Team] = None
    last_update: float = 0.0
    robot_history: Dict[int, List[Dict]] = field(default_factory=dict)  # for learning

# -----------------------------
# AI SYSTEM
# -----------------------------

class AdaptiveAI:
    def __init__(self, game_state: GameState, robots: List[Robot]):
        self.game_state = game_state
        self.robots = robots
        self.difficulty_level = 1.0  # 1.0 = normal, >1.0 = harder
        self.performance_buffer = deque(maxlen=20)  # Track recent performance
        self.strategy_weights = {
            Role.ATTACKER: 0.3,
            Role.DEFENDER: 0.2,
            Role.SUPPORT: 0.2,
            Role.SCOUT: 0.15,
            Role.CAPTURER: 0.15
        }
        self.learning_rate = 0.1
        self.adaptation_cooldown = 0
        self.adaptation_timer = 0

    def calculate_team_performance(self) -> float:
        """Calculate overall team performance based on objectives and kills"""
        total_score = 0
        for team in Team:
            total_score += self.game_state.team_scores[team]

        if total_score == 0:
            return 0.5  # Neutral

        # Calculate average score per team
        avg_score = total_score / len(Team)
        # Return a normalized performance value between 0 and 1
        performance = min(avg_score / 10, 1.0)  # Assume 10 points is considered good
        return performance

    def adjust_difficulty(self):
        """Adjust AI difficulty based on team performance"""
        if self.adaptation_cooldown > 0:
            self.adaptation_cooldown -= 1
            return

        performance = self.calculate_team_performance()
        self.performance_buffer.append(performance)

        # Average recent performance
        avg_performance = sum(self.performance_buffer) / len(self.performance_buffer) if self.performance_buffer else 0.5

        # Adjust difficulty based on performance
        if avg_performance > 0.7:
            self.difficulty_level = min(self.difficulty_level + 0.05, 2.0)
        elif avg_performance < 0.3:
            self.difficulty_level = max(self.difficulty_level - 0.05, 0.5)

        # Reset adaptation cooldown
        self.adaptation_cooldown = 60  # 1 second at 60 FPS

    def get_robot_role(self, robot: Robot) -> Role:
        """Dynamically assign or change robot role based on team needs"""
        # Count roles in team
        role_counts = defaultdict(int)
        for r in self.robots:
            if r.team == robot.team and r.is_alive:
                role_counts[r.role] += 1

        # Calculate team needs
        total_alive = sum(1 for r in self.robots if r.team == robot.team and r.is_alive)

        # If we have too many attackers, change to defender or support
        if role_counts[Role.ATTACKER] > total_alive * 0.6 and robot.role == Role.ATTACKER:
            if role_counts[Role.SUPPORT] < total_alive * 0.2:
                return Role.SUPPORT
            elif role_counts[Role.DEFENDER] < total_alive * 0.3:
                return Role.DEFENDER

        # If we need more defenders and robot is not one
        if role_counts[Role.DEFENDER] < total_alive * 0.25 and robot.role != Role.DEFENDER:
            # Check if there are active objectives to defend
            objectives_for_team = [obj for obj in self.game_state.objectives 
                                 if obj.team_control == robot.team and obj.is_active]
            if objectives_for_team:
                return Role.DEFENDER

        # If we need more capturers and there's an objective to capture
        if role_counts[Role.CAPTURER] < total_alive * 0.2:
            objectives_needing_capture = [obj for obj in self.game_state.objectives 
                                        if obj.team_control != robot.team and obj.is_active]
            if objectives_needing_capture and robot.role != Role.CAPTURER:
                return Role.CAPTURER

        # If we need scouts (no enemies detected nearby)
        if role_counts[Role.SCOUT] < total_alive * 0.15:
            # Check if enemies are out of range for most robots
            nearby_enemies = 0
            for r in self.robots:
                if r.team != robot.team and r.is_alive:
                    if robot.position.distance_to(r.position) < 300:
                        nearby_enemies += 1

            if nearby_enemies < 1:  # Not enough enemy awareness
                return Role.SCOUT

        # Default role
        return robot.role

    def get_best_target(self, robot: Robot) -> Optional[Robot]:
        """Find the best target for the robot based on AI difficulty and environment"""
        if not any(r.is_alive for r in self.robots if r.team != robot.team):
            return None

        # Filter alive enemies
        enemies = [r for r in self.robots if r.team != robot.team and r.is_alive]

        if not enemies:
            return None

        # Calculate scores for each enemy
        enemy_scores = []
        for enemy in enemies:
            distance = robot.position.distance_to(enemy.position)

            # Base score - closer enemies are better
            score = 1.0 / (1.0 + distance * 0.01)

            # Health factor - lower health targets are more attractive
            health_factor = 1 - (enemy.health / enemy.max_health)

            # Armor factor - less armored targets are easier to kill
            armor_factor = 1 - (enemy.armor / 100)

            # Objective proximity - if enemy is near an objective we're trying to capture
            objective_proximity = 0
            for obj in self.game_state.objectives:
                if obj.team_control != robot.team and obj.is_active:
                    obj_dist = enemy.position.distance_to(obj.position)
                    if obj_dist < 100:
                        objective_proximity += (100 - obj_dist) / 100

            # AI difficulty multiplier
            difficulty_multiplier = 1.0 + (self.difficulty_level - 1.0) * 0.5

            # Final score
            final_score = (score * 0.4 + 
                          health_factor * 0.3 + 
                          armor_factor * 0.2 + 
                          objective_proximity * 0.1) * difficulty_multiplier

            enemy_scores.append((enemy, final_score))

        # Sort by score and return best target
        enemy_scores.sort(key=lambda x: x[1], reverse=True)
        if enemy_scores and enemy_scores[0][1] > 0.1:
            return enemy_scores[0][0]
        return None

    def make_decision(self, robot: Robot, delta_time: float) -> Dict[str, Any]:
        """Generate a decision for the robot based on current state"""
        if not robot.is_alive:
            return {"action": "idle"}

        # Update role based on team needs
        robot.role = self.get_robot_role(robot)

        # Update strategy history
        if time.time() - robot.last_decision_time > 0.5:  # Every 0.5 seconds
            robot.strategy_history.append({
                "timestamp": time.time(),
                "role": robot.role.value,
                "health": robot.health,
                "power_ups": list(robot.power_ups.keys()),
                "team_score": self.game_state.team_scores[robot.team],
                "enemy_count": sum(1 for r in self.robots if r.team != robot.team and r.is_alive)
            })
            robot.last_decision_time = time.time()

        # Determine action based on role and environment
        if robot.role == Role.ATTACKER:
            target = self.get_best_target(robot)
            if target and robot.can_use_weapon() and robot.position.distance_to(target.position) < robot.weapon.range:
                return {"action": "attack", "target": target.id}
            elif target:
                return {"action": "move", "target": target.position}
            else:
                # Look for objectives to attack
                objectives = [obj for obj in self.game_state.objectives 
                            if obj.team_control != robot.team and obj.is_active]
                if objectives:
                    target_obj = min(objectives, key=lambda x: robot.position.distance_to(x.position))
                    return {"action": "move", "target": target_obj.position}
                else:
                    return {"action": "patrol", "target": self.random_patrol_point(robot)}

        elif robot.role == Role.DEFENDER:
            # Defend objectives owned by team
            team_objectives = [obj for obj in self.game_state.objectives 
                             if obj.team_control == robot.team and obj.is_active]
            if team_objectives:
                # Find the most threatened objective
                threat_scores = []
                for obj in team_objectives:
                    enemies_near = sum(1 for r in self.robots 
                                     if r.team != robot.team and r.is_alive 
                                     and robot.position.distance_to(r.position) < 150)
                    threat_score = enemies_near * 10 + (1 - obj.progress)
                    threat_scores.append((obj, threat_score))

                if threat_scores:
                    best_obj = max(threat_scores, key=lambda x: x[1])[0]
                    return {"action": "defend", "target": best_obj.position}
                else:
                    return {"action": "patrol", "target": self.random_patrol_point(robot)}
            else:
                # Look for enemy approaches
                enemies = [r for r in self.robots if r.team != robot.team and r.is_alive]
                if enemies:
                    # Move toward the closest enemy
                    closest_enemy = min(enemies, key=lambda x: robot.position.distance_to(x.position))
                    return {"action": "move", "target": closest_enemy.position}
                else:
                    return {"action": "patrol", "target": self.random_patrol_point(robot)}

        elif robot.role == Role.SUPPORT:
            # Heal teammates or provide power-ups
            teammates = [r for r in self.robots if r.team == robot.team and r.is_alive and r != robot]
            low_health_teammates = [r for r in teammates if r.health < r.max_health * 0.5]

            if low_health_teammates:
                closest = min(low_health_teammates, key=lambda x: robot.position.distance_to(x.position))
                return {"action": "heal", "target": closest.id}

            # Look for power-ups to collect
            active_power_ups = [pu for pu in self.game_state.power_ups if pu.is_active]
            if active_power_ups:
                closest_power_up = min(active_power_ups, key=lambda x: robot.position.distance_to(x.position))
                return {"action": "collect", "target": closest_power_up.position}

            # Otherwise, move to support objectives
            objectives = [obj for obj in self.game_state.objectives if obj.is_active]
            if objectives:
                closest_obj = min(objectives, key=lambda x: robot.position.distance_to(x.position))
                return {"action": "move", "target": closest_obj.position}
            else:
                return {"action": "patrol", "target": self.random_patrol_point(robot)}

        elif robot.role == Role.SCOUT:
            # Move to high ground or areas with less coverage
            # Just move to a random point away from teammates
            teammates = [r for r in self.robots if r.team == robot.team and r.is_alive and r != robot]
            if teammates:
                # Find farthest point from teammates
                max_dist = 0
                best_point = None
                for _ in range(5):  # Try 5 random points
                    point = Vector2(
                        random.uniform(0, GAME_WIDTH),
                        random.uniform(0, GAME_HEIGHT)
                    )
                    min_dist_to_teammates = min(point.distance_to(t.position) for t in teammates)
                    if min_dist_to_teammates > max_dist:
                        max_dist = min_dist_to_teammates
                        best_point = point

                if best_point:
                    return {"action": "move", "target": best_point}

            return {"action": "patrol", "target": self.random_patrol_point(robot)}

        elif robot.role == Role.CAPTURER:
            # Focus on capturing objectives
            objectives = [obj for obj in self.game_state.objectives 
                         if obj.team_control != robot.team and obj.is_active]
            if objectives:
                closest_obj = min(objectives, key=lambda x: robot.position.distance_to(x.position))
                return {"action": "capture", "target": closest_obj.position}
            else:
                # Look for enemies to eliminate
                enemies = [r for r in self.robots if r.team != robot.team and r.is_alive]
                if enemies:
                    closest_enemy = min(enemies, key=lambda x: robot.position.distance_to(x.position))
                    return {"action": "move", "target": closest_enemy.position}
                else:
                    return {"action": "patrol", "target": self.random_patrol_point(robot)}

        # Default action
        return {"action": "patrol", "target": self.random_patrol_point(robot)}

    def random_patrol_point(self, robot: Robot) -> Vector2:
        """Generate a random patrol point away from current position"""
        # Create a point in a reasonable range around the robot
        angle = random.uniform(0, 2 * math.pi)
        distance = random.uniform(50, 200)

        return Vector2(
            robot.position.x + math.cos(angle) * distance,
            robot.position.y + math.sin(angle) * distance
        )

