class CyberArena:
    def __init__(self):
        self.game_state = GameState()
        self.robots: List[Robot] = []
        self.ai_system: Optional[AdaptiveAI] = None
        self.particles: List[Dict] = []  # For visual effects
        self.sounds: queue.Queue = queue.Queue()  # For audio feedback
        self.time_step = 1.0 / UPDATE_RATE
        self.last_update = time.time()
        self.is_running = False
        self.control_schemes = {
            "keyboard": {"move": "wasd", "attack": "space", "switch": "tab"},
            "gamepad": {"move": "left_stick", "attack": "rt", "switch": "lb"}
        }
        self.current_control_scheme = "keyboard"

        # Initialize game
        self.initialize_game()

    def initialize_game(self):
        """Initialize the game state with robots and environment"""
        # Create robots
        robot_id = 0
        for team in Team:
            for i in range(NUM_ROBOTS_PER_TEAM):
                # Random position within team spawn area
                if team == Team.RED:
                    spawn_x = random.uniform(100, 300)
                    spawn_y = random.uniform(100, GAME_HEIGHT - 100)
                else:  # BLUE
                    spawn_x = random.uniform(GAME_WIDTH - 300, GAME_WIDTH - 100)
                    spawn_y = random.uniform(100, GAME_HEIGHT - 100)

                # Random weapon type
                weapon_types = [
                    WeaponType.RANGED, WeaponType.MELEE, WeaponType.EXPLOSIVE, WeaponType.SUPPORT
                ]
                weapon_type = random.choice(weapon_types)

                # Configure weapon based on type
                if weapon_type == WeaponType.RANGED:
                    weapon = Weapon(WeaponType.RANGED, 25, 1.0, 300)
                elif weapon_type == WeaponType.MELEE:
                    weapon = Weapon(WeaponType.MELEE, 50, 2.5, 80)
                elif weapon_type == WeaponType.EXPLOSIVE:
                    weapon = Weapon(WeaponType.EXPLOSIVE, 75, 5.0, 150)
                else:  # SUPPORT
                    weapon = Weapon(WeaponType.SUPPORT, 15, 3.0, 200)

                robot = Robot(
                    id=robot_id,
                    team=team,
                    position=Vector2(spawn_x, spawn_y),
                    weapon=weapon
                )
                self.robots.append(robot)
                robot_id += 1

        # Create objectives
        self.game_state.objectives = [
            Objective(
                type=ObjectiveType.FLAG_CAPTURE,
                position=Vector2(GAME_WIDTH/2, 200),
                team=Team.RED,
                capture_radius=60,
                capture_time=15.0
            ),
            Objective(
                type=ObjectiveType.FLAG_CAPTURE,
                position=Vector2(GAME_WIDTH/2, GAME_HEIGHT - 200),
                team=Team.BLUE,
                capture_radius=60,
                capture_time=15.0
            ),
            Objective(
                type=ObjectiveType.PAYLOAD_ESCORT,
                position=Vector2(GAME_WIDTH/4, GAME_HEIGHT/2),
                team=None,
                capture_radius=80,
                capture_time=20.0
            ),
            Objective(
                type=ObjectiveType.BASE_DEFENSE,
                position=Vector2(150, GAME_HEIGHT/2),
                team=Team.RED,
                capture_radius=100,
                capture_time=10.0
            ),
            Objective(
                type=ObjectiveType.BASE_DEFENSE,
                position=Vector2(GAME_WIDTH - 150, GAME_HEIGHT/2),
                team=Team.BLUE,
                capture_radius=100,
                capture_time=10.0
            )
        ]

        # Create power-ups
        power_up_types = [
            PowerUpType.SPEED_BOOST, PowerUpType.SHIELD, PowerUpType.DAMAGE_BOOST,
            PowerUpType.REGEN, PowerUpType.SILENCE
        ]

        for i in range(5):
            power_up_type = random.choice(power_up_types)
            position = Vector2(
                random.uniform(100, GAME_WIDTH - 100),
                random.uniform(100, GAME_HEIGHT - 100)
            )
            power_up = PowerUp(
                type=power_up_type,
                position=position,
                duration=15.0
            )
            self.game_state.power_ups.append(power_up)

        # Create hazards
        hazard_types = [
            HazardType.LAVA, HazardType.ELECTRIC_FIELD, HazardType.MINE_FIELD, HazardType.GRAVITY_WELL
        ]

        for i in range(3):
            hazard_type = random.choice(hazard_types)
            position = Vector2(
                random.uniform(200, GAME_WIDTH - 200),
                random.uniform(200, GAME_HEIGHT - 200)
            )
            radius = random.uniform(60, 120)
            damage_per_second = random.uniform(5, 15)

            hazard = Hazard(
                type=hazard_type,
                position=position,
                radius=radius,
                damage_per_second=damage_per_second
            )
            self.game_state.hazards.append(hazard)

        # Initialize AI system
        self.ai_system = AdaptiveAI(self.game_state, self.robots)

        # Start round
        self.game_state.round_start_time = time.time()
        self.game_state.is_round_active = True
        self.game_state.last_update = time.time()

        # Initialize robot history for learning
        for robot in self.robots:
            self.game_state.robot_history[robot.id] = []

    def update(self, delta_time: float) -> bool:
        """Update the game state for one frame"""
        if not self.game_state.is_round_active:
            return False

        # Update time
        self.game_state.time += delta_time

        # Check if round is over
        if self.game_state.time >= self.game_state.round_duration:
            self.end_round()
            return False

        # Update AI difficulty
        self.ai_system.adjust_difficulty()

        # Process robot decisions
        for robot in self.robots:
            if not robot.is_alive:
                continue

            # Update cooldowns and power-ups
            robot.update_cooldowns(delta_time)
            robot.update_power_ups(delta_time)

            # Apply power-up effects
            if PowerUpType.SPEED_BOOST in robot.power_ups:
                robot.movement_speed = 5.0
            if PowerUpType.DAMAGE_BOOST in robot.power_ups:
                robot.weapon.damage = robot.weapon.base_damage * 1.5
            if PowerUpType.SHIELD in robot.power_ups:
                robot.armor = 50.0

            # Make AI decision
            if self.is_ai_robot(robot):  # All robots are AI in this implementation
                decision = self.ai_system.make_decision(robot, delta_time)
                self.execute_robot_decision(robot, decision, delta_time)

        # Update objectives
        self.update_objectives(delta_time)

        # Update power-ups
        self.update_power_ups(delta_time)

        # Update hazards
        self.update_hazards(delta_time)

        # Update particles
        self.update_particles(delta_time)

        # Check for team wins
        self.check_for_win_condition()

        # Update last update time
        self.game_state.last_update = time.time()

        return True

    def is_ai_robot(self, robot: Robot) -> bool:
        """All robots in this implementation are AI-controlled"""
        return True

    def execute_robot_decision(self, robot: Robot, decision: Dict[str, Any], delta_time: float):
        """Execute a decision made by the AI system"""
        action = decision["action"]

        if action == "attack":
            target_id = decision["target"]
            target_robot = next((r for r in self.robots if r.id == target_id), None)
            if target_robot and target_robot.is_alive:
                # Calculate if in range
                distance = robot.position.distance_to(target_robot.position)
                if distance <= robot.weapon.range:
                    # Apply weapon damage
                    damage = robot.weapon.damage
                    actual_damage = target_robot.take_damage(damage)

                    # Create particle effect
                    self.create_particle(
                        target_robot.position,
                        "explosion", 
                        color=(255, 100, 100),
                        lifetime=0.8
                    )

                    # Play sound
                    self.play_sound("hit", 0.7)

                    # Add to strategy history
                    robot.strategy_history.append({
                        "action": "attack",
                        "target": target_id,
                        "damage": actual_damage,
                        "timestamp": time.time()
                    })

                    # Reset weapon cooldown
                    robot.cooldowns["weapon"] = robot.weapon.cooldown

        elif action == "move":
            target = decision["target"]
            if isinstance(target, Vector2):
                # Move toward target
                direction = (target - robot.position).normalize()
                movement = direction * robot.movement_speed * delta_time * 60  # Scale to FPS

                # Apply movement
                robot.position = robot.position + movement

                # Keep robot within bounds
                robot.position.x = max(0, min(robot.position.x, GAME_WIDTH))
                robot.position.y = max(0, min(robot.position.y, GAME_HEIGHT))

                # Create movement trail effect
                if random.random() < 0.3:  # 30% chance per update
                    self.create_particle(
                        robot.position,
                        "trail", 
                        color=(100, 100, 255) if robot.team == Team.BLUE else (255, 100, 100),
                        lifetime=0.5
                    )

        elif action == "defend":
