            self.facing = math.atan2(direction.y, direction.x)

    def rotate_towards(self, target: Vector2D):
        if not self.is_alive:
            return

        direction = (target - self.position)
        if direction.x != 0 or direction.y != 0:
            self.facing = math.atan2(direction.y, direction.x)

    def get_distance_to(self, other: Vector2D) -> float:
        return self.position.distance_to(other)

    def get_view_direction(self) -> Vector2D:
        return Vector2D(math.cos(self.facing), math.sin(self.facing))

    def get_targets_in_range(self, robots: List['Robot'], range_limit: float) -> List['Robot']:
        targets = []
        for robot in robots:
            if robot.team != self.team and robot.is_alive and self.get_distance_to(robot.position) <= range_limit:
                targets.append(robot)
        return targets

    def get_team_members_in_range(self, robots: List['Robot'], range_limit: float) -> List['Robot']:
        teammates = []
        for robot in robots:
            if robot.team == self.team and robot.is_alive and self.get_distance_to(robot.position) <= range_limit:
                teammates.append(robot)
        return teammates

    def update_memory(self, key: str, value: Any):
        self.memory[key] = value

    def get_memory(self, key: str, default: Any = None) -> Any:
        return self.memory.get(key, default)

    def add_strategy(self, strategy: str):
        self.strategy_history.append(strategy)
        # Keep history limited to prevent memory bloat
        if len(self.strategy_history) > 100:
            self.strategy_history.pop(0)

    def get_recent_strategy(self, count: int = 5) -> List[str]:
        return self.strategy_history[-count:] if len(self.strategy_history) >= count else self.strategy_history

