class AIController:
    def __init__(self, robot: Robot, arena: 'CyberArena'):
        self.robot = robot
        self.arena = arena
        self.current_command: Optional[AICommand] = None
        self.command_queue: List[AICommand] = []
        self.last_strategy_update = 0.0
        self.strategy_cooldown = 5.0  # seconds between strategy evaluations

        # AI learning parameters
        self.learning_rate = 0.1
        self.exploration_rate = 0.3
        self.decay_rate = 0.995

        # Historical data for learning
        self.last_outcome = 0.0  # performance score (0-1)
        self.known_enemy_patterns = {}
        self.team_roles = {}

    def update(self, delta_time: float):
        if not self.robot.is_alive:
            return

        # Update durations of power-ups and stealth
        self.robot.update_durations(delta_time)

        # Update strategy every few seconds
        if self.arena.current_time - self.last_strategy_update > self.strategy_cooldown:
            self._evaluate_strategy()
            self.last_strategy_update = self.arena.current_time

        # Execute current command or get new one
        if self.current_command is None or not self.current_command.execute(self.robot, self.arena):
            self.current_command = self._select_command()

        # Execute the chosen command
        if self.current_command:
            self.current_command.execute(self.robot, self.arena)

    def _evaluate_strategy(self):
        """Evaluate performance and adapt strategy"""
        if not self.robot.is_alive:
            return

        # Calculate performance score
        total_damage_dealt = 0
        total_damage_taken = 0
        objectives_completed = 0
        teammates_saved = 0

        # Gather stats from robot's memory
        for key, value in self.robot.memory.items():
            if key.startswith("damage_dealt_"):
                total_damage_dealt += value
            elif key.startswith("damage_taken_"):
                total_damage_taken += value
            elif key.startswith("objective_completed_"):
                objectives_completed += 1
            elif key.startswith("teammate_saved_"):
                teammates_saved += 1

        # Performance score (0-1)
        self.last_outcome = min(1.0, max(0.0, (total_damage_dealt * 0.4 + objectives_completed * 0.3 + teammates_saved * 0.2 - total_damage_taken * 0.1) / 100))

        # Adjust behavior based on performance
        if self.last_outcome < 0.3:
            # Poor performance - become more aggressive or change role
            if self.robot.role == RobotRole.DEFENDER:
                self.robot.role = RobotRole.ATTACKER
                self.robot.add_strategy("Switched from Defender to Attacker due to low performance")
            elif self.robot.role == RobotRole.SUPPORT:
                self.robot.role = RobotRole.SCATTER
                self.robot.add_strategy("Switched from Support to Scout due to low performance")
        elif self.last_outcome > 0.7:
            # Good performance - become more strategic or take on leadership role
            if self.robot.role == RobotRole.ATTACKER and len(self.arena.get_team_members(self.robot.team)) > 1:
                # Try to coordinate with others
                teammates = self.robot.get_team_members_in_range(self.arena.robots, 20.0)
                if len(teammates) >= 2:
                    self.robot.role = RobotRole.CONTROLLER
                    self.robot.add_strategy("Promoted to Controller due to high performance")

        # Adapt to enemy patterns
        if self.robot.last_seen_enemies:
            for enemy_id, position, time_seen in self.robot.last_seen_enemies:
                if enemy_id not in self.known_enemy_patterns:
                    self.known_enemy_patterns[enemy_id] = []
                self.known_enemy_patterns[enemy_id].append((position, time_seen))

                # Detect patterns (e.g., frequent movement to a location)
                if len(self.known_enemy_patterns[enemy_id]) > 5:
                    recent_positions = self.known_enemy_patterns[enemy_id][-5:]
                    avg_pos = Vector2D(
                        sum(p[0].x for p in recent_positions) / 5,
                        sum(p[0].y for p in recent_positions) / 5
                    )
                    if avg_pos.distance_to(recent_positions[-1][0]) < 3:
                        # Enemy is likely hiding or camping
                        self.robot.update_memory(f"enemy_{enemy_id}_camping", True)

    def _select_command(self) -> Optional[AICommand]:
        """Select the next command based on role, objectives, and current situation"""
        if not self.robot.is_alive:
            return None

        # Identify key objectives
        objectives_in_range = []
        for obj in self.arena.objectives:
            if obj.team != self.robot.team or obj.captured:
                # Enemy objective or already captured
                if self.robot.get_distance_to(obj.position) < 40.0:
                    objectives_in_range.append(obj)

        # Find teammates in need
        teammates_in_danger = []
        teammates = self.robot.get_team_members_in_range(self.arena.robots, 30.0)
        for teammate in teammates:
            if teammate.stats.health < teammate.stats.max_health * 0.3:
                teammates_in_danger.append(teammate)

        # Find enemies to attack
        enemies = self.robot.get_targets_in_range(self.arena.robots, 60.0)

        # Priority: 1. Capture objectives, 2. Defend objectives, 3. Attack enemies, 4. Support teammates, 5. Scout

        if self.robot.role == RobotRole.ATTACKER:
            # Attackers prioritize capturing enemy objectives
            if objectives_in_range:
                # Find the objective with most progress (easiest to capture)
                target_obj = min(objectives_in_range, key=lambda o: (o.captured, o.progress))
                if target_obj.team != self.robot.team:
                    return CaptureCommand(target_obj)

            # If no objectives to capture, attack closest enemy
            if enemies:
                return AttackCommand(enemies[0].id)

        elif self.robot.role == RobotRole.DEFENDER:
            # Defenders prioritize defending friendly objectives
            for obj in self.arena.objectives:
                if obj.team == self.robot.team and not obj.captured:
                    return DefendCommand(obj)

            # If no objectives to defend, protect teammates
            if teammates_in_danger:
                return SupportCommand(teammates_in_danger[0].id, "cover")

            # Otherwise, hold position near base or patrol
            if self.arena.bases:
                base_pos = self.arena.bases[0].position if self.arena.bases[0].team == self.robot.team else Vector2D(0, 0)
                return MoveToCommand(base_pos)

        elif self.robot.role == RobotRole.SUPPORT:
            # Support robots prioritize healing or resupplying
            if teammates_in_danger:
                # Find the teammate with lowest health
                target = min(teammates_in_danger, key=lambda t: t.stats.health / t.stats.max_health)
                return SupportCommand(target.id, "heal")

            # If no one needs healing, check for ammo
            teammates_low_ammo = []
            for teammate in teammates:
                for weapon in teammate.weapons:
                    if weapon.ammo != -1 and weapon.ammo < weapon.max_ammo * 0.2:
                        teammates_low_ammo.append(teammate)
                        break

            if teammates_low_ammo:
                return SupportCommand(teammates_low_ammo[0].id, "ammo")

        elif self.robot.role == RobotRole.SCATTER:
            # Scouts prioritize gathering information
            if enemies:
                # Find the most distant enemy to scout
                farthest_enemy = max(enemies, key=lambda e: self.robot.get_distance_to(e.position))
                return AttackCommand(farthest_enemy.id)
            else:
                # Explore area
                return ScoutCommand("spiral")

        elif self.robot.role == RobotRole.CONTROLLER:
            # Controllers coordinate team efforts
            # Find the most critical objective
            if objectives_in_range:
                # Find objective with highest enemy progress
                target_obj = max(objectives_in_range, key=lambda o: o.progress if not o.captured else 0)
                if not target_obj.captured:
                    return CaptureCommand(target_obj)

            # Coordinate with team to defend/attack
            if teammates:
                # Try to group up with teammates
                avg_pos = Vector2D(
                    sum(t.position.x for t in teammates) / len(teammates),
                    sum(t.position.y for t in teammates) / len(teammates)
                )
                return MoveToCommand(avg_pos)

        # Default: Move to a strategic point
        if self.arena.bases:
            base_pos = self.arena.bases[0].position
            return MoveToCommand(base_pos)

        return MoveToCommand(Vector2D(0, 0))

