class Effect:
    def __init__(self, type: str, position: Vector2D, direction: Optional[Vector2D] = None, duration: float = 1.0, value: float = 1.0):
        self.type = type
        self.position = position
        self.direction = direction or Vector2D(0, 0)
        self.duration = duration
        self.lifetime = 0.0
        self.value = value  # For visual effects like health bar or capture progress

    def update(self, delta_time: float) -> bool:
        self.lifetime += delta_time
        return self.lifetime < self.duration

