class ObjectType(Enum):
    FLAG = "flag"
    BASE = "base"
    PAYLOAD = "payload"
    POWERUP = "powerup"
    HAZARD = "hazard"

class RobotRole(Enum):
    ATTACKER = "attacker"
    DEFENDER = "defender"
    SUPPORT = "support"
    SCOUT = "scout"
    CONTROLLER = "controller"

class GameState(Enum):
    PREPARE = "prepare"
    ACTIVE = "active"
    PAUSED = "paused"
    ENDED = "ended"

@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def distance_to(self, other: 'Vector2D') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def normalize(self) -> 'Vector2D':
        magnitude = math.sqrt(self.x**2 + self.y**2)
        if magnitude == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / magnitude, self.y / magnitude)

    def __add__(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar: float) -> 'Vector2D':
        return Vector2D(self.x * scalar, self.y * scalar)

    def __repr__(self):
        return f"Vector2D({self.x:.1f}, {self.y:.1f})"

@dataclass
class Weapon:
    name: str
    type: WeaponType
    damage: float
    range: float
    cooldown: float
    ammo: int = -1  # -1 means infinite
    max_ammo: int = -1
    spread: float = 0.0  # for ranged weapons
    projectile_speed: float = 10.0
    area_effect: float = 0.0  # for explosives

    def can_fire(self, current_time: float, last_fired: float) -> bool:
        return current_time - last_fired >= self.cooldown

    def use_ammo(self) -> bool:
        if self.ammo == -1:  # Infinite ammo
            return True
        if self.ammo > 0:
            self.ammo -= 1
            return True
        return False

@dataclass
class PowerUp:
    type: str  # "health", "speed", "shield", "ammo", "damage", "stealth"
    duration: float  # seconds
    value: float  # multiplier or absolute value
    visual_effect: str = "glow"

    def apply_effect(self, robot: 'Robot'):
        if self.type == "health":
            robot.health = min(robot.max_health, robot.health + self.value)
        elif self.type == "speed":
            robot.move_speed *= self.value
            robot.speed_boost_duration = self.duration
        elif self.type == "shield":
            robot.shield = min(robot.max_shield, robot.shield + self.value)
        elif self.type == "ammo":
            for weapon in robot.weapons:
                if weapon.ammo != -1:
                    weapon.ammo = min(weapon.max_ammo, weapon.ammo + int(self.value))
        elif self.type == "damage":
            for weapon in robot.weapons:
                weapon.damage *= self.value
            robot.damage_boost_duration = self.duration
        elif self.type == "stealth":
            robot.stealth = True
            robot.stealth_duration = self.duration

@dataclass
class Hazard:
    type: str  # "lava", "electric", "mine", "gas"
    damage_per_second: float
    radius: float
    active: bool = True

    def affect_robot(self, robot: 'Robot') -> float:
        if not self.active:
            return 0
        return self.damage_per_second

@dataclass
class Objective:
    type: ObjectType
    position: Vector2D
    team: Team
    captured: bool = False
    progress: float = 0.0
    required_progress: float = 1.0
    defenders: List[int] = field(default_factory=list)
    attackers: List[int] = field(default_factory=list)
    respawn_time: float = 30.0
    last_captured: float = 0.0

    def update_progress(self, robot_id: int, team: Team, delta: float):
        if team == self.team and not self.captured:
            # Defending
            if robot_id not in self.defenders:
                self.defenders.append(robot_id)
            self.progress = min(1.0, self.progress + delta * 0.01)
        elif team != self.team and not self.captured:
            # Attacking
            if robot_id not in self.attackers:
                self.attackers.append(robot_id)
            self.progress = max(0.0, self.progress - delta * 0.01)

        # Capture logic
        if self.progress >= self.required_progress and team != self.team:
            self.captured = True
            self.team = team
            self.last_captured = time.time()
            self.progress = 0.0
            self.defenders.clear()
            self.attackers.clear()
        elif self.progress <= 0 and self.captured:
            self.captured = False
            self.progress = 0.0
            self.defenders.clear()
            self.attackers.clear()

@dataclass
class RobotStats:
    health: float = 100.0
    max_health: float = 100.0
    shield: float = 0.0
    max_shield: float = 50.0
    move_speed: float = 5.0
    accuracy: float = 0.85
    reaction_time: float = 0.3
    teamwork_bonus: float = 1.0
    experience: float = 0.0
    level: int = 1

@dataclass
class Robot:
    id: int
    team: Team
    position: Vector2D
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    facing: float = 0.0  # angle in radians
    weapons: List[Weapon] = field(default_factory=list)
    stats: RobotStats = field(default_factory=RobotStats)
    role: RobotRole = RobotRole.ATTACKER
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    last_action_time: float = 0.0
    last_fired: Dict[str, float] = field(default_factory=dict)
    is_alive: bool = True
    last_seen_enemies: List[Tuple[int, Vector2D, float]] = field(default_factory=list)
    memory: Dict[str, Any] = field(default_factory=dict)
    last_update: float = 0.0
    speed_boost_duration: float = 0.0
    damage_boost_duration: float = 0.0
    stealth: bool = False
    stealth_duration: float = 0.0
    cooldowns: Dict[str, float] = field(default_factory=dict)
    team_cooperation: float = 0.5  # 0-1 scale, how well they cooperate with team
    strategy_history: List[str] = field(default_factory=list)

    def __post_init__(self):
        # Initialize last_fired for each weapon
        for weapon in self.weapons:
            self.last_fired[weapon.name] = 0.0
        self.cooldowns = {}

    def update_durations(self, delta_time: float):
        # Update power-up durations
        self.speed_boost_duration = max(0, self.speed_boost_duration - delta_time)
        self.damage_boost_duration = max(0, self.damage_boost_duration - delta_time)
        self.stealth_duration = max(0, self.stealth_duration - delta_time)

        # Apply effects
        if self.speed_boost_duration <= 0:
            self.move_speed = self.stats.move_speed
        if self.damage_boost_duration <= 0:
            for weapon in self.weapons:
                weapon.damage = weapon.damage / getattr(self, '_original_damage', 1.0) if hasattr(self, '_original_damage') else weapon.damage
        if self.stealth_duration <= 0:
            self.stealth = False

    def get_primary_weapon(self) -> Optional[Weapon]:
        return self.weapons[0] if self.weapons else None

    def can_fire_weapon(self, weapon_name: str, current_time: float) -> bool:
        return current_time - self.last_fired.get(weapon_name, 0) >= self.get_weapon_by_name(weapon_name).cooldown

    def get_weapon_by_name(self, name: str) -> Optional[Weapon]:
        for weapon in self.weapons:
            if weapon.name == name:
                return weapon
        return None

    def fire_weapon(self, weapon_name: str, target: Vector2D, current_time: float) -> bool:
        weapon = self.get_weapon_by_name(weapon_name)
        if not weapon or not weapon.can_fire(current_time, self.last_fired[weapon_name]):
            return False

        if not weapon.use_ammo():
            return False

        self.last_fired[weapon_name] = current_time
        return True

    def add_power_up(self, power_up: PowerUp):
        self.power_ups.append(power_up)
        power_up.apply_effect(self)

    def take_damage(self, damage: float, source: Optional['Robot'] = None) -> float:
        if not self.is_alive:
            return 0

        # Apply shield first
        actual_damage = damage
        if self.shield > 0:
            shield_absorbed = min(self.shield, damage)
            self.shield -= shield_absorbed
            actual_damage -= shield_absorbed

        # Then apply to health
        if actual_damage > 0:
            self.stats.health = max(0, self.stats.health - actual_damage)
            if self.stats.health <= 0:
                self.is_alive = False
                logger.info(f"Robot {self.id} (Team {self.team.value}) has been eliminated")

        return actual_damage

    def heal(self, amount: float):
        if self.is_alive:
            self.stats.health = min(self.stats.max_health, self.stats.health + amount)

    def move_towards(self, target: Vector2D, delta_time: float):
        if not self.is_alive:
            return

        direction = (target - self.position).normalize()
        self.velocity = direction * self.move_speed
        self.position = self.position + self.velocity * delta_time
        # Update facing direction
        if direction.x != 0 or direction.y != 0:
            self.facing = math.atan2(direction.y, direction.x)

    def rotate_towards(self, target: Vector2D):
        if not self.is_alive:
            return

        direction = (target - self.position)
        if direction.x != 0 or direction.y != 0:
            self.facing = math.atan2(direction.y, direction.x)

    def get_distance_to(self, other: Vector2D) -> float:
        return self.position.distance_to(other)

    def get_view_direction(self) -> Vector2D:
        return Vector2D(math.cos(self.facing), math.sin(self.facing))

    def get_targets_in_range(self, robots: List['Robot'], range_limit: float) -> List['Robot']:
        targets = []
        for robot in robots:
            if robot.team != self.team and robot.is_alive and self.get_distance_to(robot.position) <= range_limit:
                targets.append(robot)
        return targets

    def get_team_members_in_range(self, robots: List['Robot'], range_limit: float) -> List['Robot']:
        teammates = []
        for robot in robots:
            if robot.team == self.team and robot.is_alive and self.get_distance_to(robot.position) <= range_limit:
                teammates.append(robot)
        return teammates

    def update_memory(self, key: str, value: Any):
        self.memory[key] = value

    def get_memory(self, key: str, default: Any = None) -> Any:
        return self.memory.get(key, default)

    def add_strategy(self, strategy: str):
        self.strategy_history.append(strategy)
        # Keep history limited to prevent memory bloat
        if len(self.strategy_history) > 100:
            self.strategy_history.pop(0)

    def get_recent_strategy(self, count: int = 5) -> List[str]:
        return self.strategy_history[-count:] if len(self.strategy_history) >= count else self.strategy_history

