class AICommand(ABC):
    """Abstract base class for AI commands"""

    @abstractmethod
    def execute(self, robot: Robot, arena: 'CyberArena') -> bool:
        pass

class MoveToCommand(AICommand):
    def __init__(self, target: Vector2D, avoid_enemies: bool = True):
        self.target = target
        self.avoid_enemies = avoid_enemies

    def execute(self, robot: Robot, arena: 'CyberArena') -> bool:
        if not robot.is_alive:
            return False

        # Check if target is reachable (not inside obstacle)
        if self.avoid_enemies:
            # Simple collision avoidance
            enemies = robot.get_targets_in_range(arena.robots, 15.0)
            if enemies:
                # Try to avoid closest enemy
                closest_enemy = min(enemies, key=lambda r: robot.get_distance_to(r.position))
                if robot.get_distance_to(closest_enemy.position) < 8.0:
                    # Move perpendicular to enemy direction
                    direction_to_enemy = (closest_enemy.position - robot.position).normalize()
                    perpendicular = Vector2D(-direction_to_enemy.y, direction_to_enemy.x)
                    self.target = robot.position + perpendicular * 10.0

        robot.move_towards(self.target, arena.delta_time)
        return True

class AttackCommand(AICommand):
    def __init__(self, target_id: Optional[int] = None):
        self.target_id = target_id

    def execute(self, robot: Robot, arena: 'CyberArena') -> bool:
        if not robot.is_alive:
            return False

        target_robot = None
        if self.target_id is not None:
            target_robot = next((r for r in arena.robots if r.id == self.target_id and r.is_alive and r.team != robot.team), None)

        if not target_robot:
            # Find closest enemy
            enemies = robot.get_targets_in_range(arena.robots, 50.0)
            if not enemies:
                return False
            target_robot = min(enemies, key=lambda r: robot.get_distance_to(r.position))

        # Rotate towards target
        robot.rotate_towards(target_robot.position)

        # Check if in firing range
        weapon = robot.get_primary_weapon()
        if weapon and weapon.type == WeaponType.RANGED:
            distance = robot.get_distance_to(target_robot.position)
            if distance <= weapon.range:
                # Fire if cooldown is ready
                if robot.can_fire_weapon(weapon.name, arena.current_time):
                    # Simple aim prediction (lead target)
                    # Calculate where target will be based on velocity and projectile speed
                    direction = (target_robot.position - robot.position).normalize()
                    projected_target = target_robot.position + target_robot.velocity * (distance / weapon.projectile_speed)
                    aim_direction = (projected_target - robot.position).normalize()

                    # Apply accuracy factor (random spread)
                    angle_offset = random.gauss(0, (1 - robot.stats.accuracy) * 0.3)
                    aim_direction = Vector2D(
                        aim_direction.x * math.cos(angle_offset) - aim_direction.y * math.sin(angle_offset),
                        aim_direction.x * math.sin(angle_offset) + aim_direction.y * math.cos(angle_offset)
                    )

                    # Fire weapon
                    if robot.fire_weapon(weapon.name, projected_target, arena.current_time):
                        # Create projectile effect
                        arena.add_effect("bullet_trail", robot.position, aim_direction, weapon.projectile_speed)
                        logger.info(f"Robot {robot.id} fired {weapon.name} at Robot {target_robot.id}")
                        return True

        elif weapon and weapon.type == WeaponType.MELEE:
            distance = robot.get_distance_to(target_robot.position)
            if distance <= weapon.range:
                # Execute melee attack
                if robot.can_fire_weapon(weapon.name, arena.current_time):
                    robot.fire_weapon(weapon.name, target_robot.position, arena.current_time)
                    target_robot.take_damage(weapon.damage * robot.stats.teamwork_bonus)
                    arena.add_effect("melee_impact", target_robot.position)
                    logger.info(f"Robot {robot.id} melee attacked Robot {target_robot.id}")
                    return True

        return False

class DefendCommand(AICommand):
    def __init__(self, objective: Objective):
        self.objective = objective

    def execute(self, robot: Robot, arena: 'CyberArena') -> bool:
        if not robot.is_alive:
            return False

        # Move to objective position if not near it
        if robot.get_distance_to(self.objective.position) > 8.0:
            robot.move_towards(self.objective.position, arena.delta_time)
            return True

        # If near objective, rotate to cover multiple angles
        # Look for approaching enemies
        enemies = robot.get_targets_in_range(arena.robots, 30.0)
        if enemies:
            closest_enemy = min(enemies, key=lambda r: robot.get_distance_to(r.position))
            robot.rotate_towards(closest_enemy.position)

            # Attack if in range
            weapon = robot.get_primary_weapon()
            if weapon and weapon.type == WeaponType.RANGED:
                distance = robot.get_distance_to(closest_enemy.position)
                if distance <= weapon.range and robot.can_fire_weapon(weapon.name, arena.current_time):
                    robot.fire_weapon(weapon.name, closest_enemy.position, arena.current_time)
                    arena.add_effect("bullet_trail", robot.position, (closest_enemy.position - robot.position).normalize(), weapon.projectile_speed)
                    return True

        return True

class CaptureCommand(AICommand):
    def __init__(self, objective: Objective):
        self.objective = objective

    def execute(self, robot: Robot, arena: 'CyberArena') -> bool:
        if not robot.is_alive:
            return False

        # Move towards objective
        robot.move_towards(self.objective.position, arena.delta_time)

        # Update objective progress
        if robot.get_distance_to(self.objective.position) < 5.0:
            self.objective.update_progress(robot.id, robot.team, 0.02)
            # Visual feedback
            arena.add_effect("capture_progress", self.objective.position, value=self.objective.progress)

            # Check if objective captured
            if self.objective.captured and self.objective.team == robot.team:
                robot.stats.experience += 10
                arena.add_effect("captured", self.objective.position)
                logger.info(f"Robot {robot.id} captured {self.objective.type.value} for team {robot.team.value}")

                # Add team cooperation bonus
                teammates = robot.get_team_members_in_range(arena.robots, 20.0)
                for teammate in teammates:
                    teammate.team_cooperation += 0.02
                    teammate.stats.experience += 5

        return True

class EscortCommand(AICommand):
    def __init__(self, payload: Objective, escort_position: Vector2D):
        self.payload = payload
        self.escort_position = escort_position

    def execute(self, robot: Robot, arena: 'CyberArena') -> bool:
        if not robot.is_alive:
            return False

        # Stay near payload
        if robot.get_distance_to(self.payload.position) > 12.0:
            robot.move_towards(self.payload.position, arena.delta_time)

        # Protect payload from enemies
        enemies = robot.get_targets_in_range(arena.robots, 25.0)
        if enemies:
            closest_enemy = min(enemies, key=lambda r: robot.get_distance_to(r.position))
            robot.rotate_towards(closest_enemy.position)

            # Attack if in range
            weapon = robot.get_primary_weapon()
            if weapon and weapon.type == WeaponType.RANGED:
                distance = robot.get_distance_to(closest_enemy.position)
                if distance <= weapon.range and robot.can_fire_weapon(weapon.name, arena.current_time):
                    robot.fire_weapon(weapon.name, closest_enemy.position, arena.current_time)
                    arena.add_effect("bullet_trail", robot.position, (closest_enemy.position - robot.position).normalize(), weapon.projectile_speed)
                    return True

        return True

class ScoutCommand(AICommand):
    def __init__(self, search_pattern: str = "spiral"):
        self.search_pattern = search_pattern
        self.search_radius = 20.0
        self.search_angle = 0.0
        self.search_step = 0.0

    def execute(self, robot: Robot, arena: 'CyberArena') -> bool:
        if not robot.is_alive:
            return False

        # Use different search patterns
        if self.search_pattern == "spiral":
            # Spiral outward
            self.search_radius += 0.1
            self.search_angle += 0.1
            target_x = robot.position.x + math.cos(self.search_angle) * self.search_radius
            target_y = robot.position.y + math.sin(self.search_angle) * self.search_radius
            target = Vector2D(target_x, target_y)

            # If we've gone too far, reset
            if self.search_radius > 50.0:
                self.search_radius = 20.0
                self.search_angle = 0.0

            robot.move_towards(target, arena.delta_time)

        elif self.search_pattern == "grid":
            # Grid pattern
            step_size = 15.0
            self.search_step += arena.delta_time * 2
            grid_x = int(robot.position.x / step_size)
            grid_y = int(robot.position.y / step_size)

            target_x = (grid_x + math.sin(self.search_step)) * step_size
            target_y = (grid_y + math.cos(self.search_step)) * step_size
            target = Vector2D(target_x, target_y)

            robot.move_towards(target, arena.delta_time)

        # Look for enemies while scouting
        enemies = robot.get_targets_in_range(arena.robots, 40.0)
        for enemy in enemies:
            robot.update_memory(f"enemy_{enemy.id}", (enemy.position, arena.current_time))
            logger.info(f"Scout {robot.id} spotted enemy {enemy.id} at {enemy.position}")

        return True

class SupportCommand(AICommand):
    def __init__(self, target_robot_id: int, support_type: str = "heal"):
        self.target_robot_id = target_robot_id
        self.support_type = support_type  # "heal", "ammo", "shield", "cover"

    def execute(self, robot: Robot, arena: 'CyberArena') -> bool:
        if not robot.is_alive:
            return False

        target_robot = next((r for r in arena.robots if r.id == self.target_robot_id and r.is_alive and r.team == robot.team), None)
        if not target_robot:
            return False

        # Move towards teammate
        if robot.get_distance_to(target_robot.position) > 10.0:
            robot.move_towards(target_robot.position, arena.delta_time)

        # Apply support effect
        if self.support_type == "heal" and robot.get_distance_to(target_robot.position) <= 8.0:
            # Use a healing ability
            for weapon in robot.weapons:
                if weapon.type == WeaponType.SPECIAL and "heal" in weapon.name.lower():
                    if robot.can_fire_weapon(weapon.name, arena.current_time) and target_robot.stats.health < target_robot.stats.max_health:
                        robot.fire_weapon(weapon.name, target_robot.position, arena.current_time)
                        target_robot.heal(weapon.damage * 0.5)  # Healing amount
                        arena.add_effect("heal_beam", target_robot.position)
                        logger.info(f"Robot {robot.id} healed Robot {target_robot.id}")
                        return True

        elif self.support_type == "ammo" and robot.get_distance_to(target_robot.position) <= 8.0:
            # Use an ammo resupply ability
            for weapon in robot.weapons:
                if weapon.type == WeaponType.SPECIAL and "ammo" in weapon.name.lower():
                    if robot.can_fire_weapon(weapon.name, arena.current_time):
                        robot.fire_weapon(weapon.name, target_robot.position, arena.current_time)
                        for w in target_robot.weapons:
                            if w.ammo != -1:
                                w.ammo = min(w.max_ammo, w.ammo + 10)
                        logger.info(f"Robot {robot.id} resupplied Robot {target_robot.id} with ammo")
                        return True

        return True

class AIController:
    def __init__(self, robot: Robot, arena: 'CyberArena'):
        self.robot = robot
        self.arena = arena
        self.current_command: Optional[AICommand] = None
        self.command_queue: List[AICommand] = []
        self.last_strategy_update = 0.0
        self.strategy_cooldown = 5.0  # seconds between strategy evaluations

        # AI learning parameters
        self.learning_rate = 0.1
        self.exploration_rate = 0.3
        self.decay_rate = 0.995

        # Historical data for learning
        self.last_outcome = 0.0  # performance score (0-1)
        self.known_enemy_patterns = {}
        self.team_roles = {}

    def update(self, delta_time: float):
        if not self.robot.is_alive:
            return

        # Update durations of power-ups and stealth
        self.robot.update_durations(delta_time)

        # Update strategy every few seconds
        if self.arena.current_time - self.last_strategy_update > self.strategy_cooldown:
            self._evaluate_strategy()
            self.last_strategy_update = self.arena.current_time

        # Execute current command or get new one
        if self.current_command is None or not self.current_command.execute(self.robot, self.arena):
            self.current_command = self._select_command()

        # Execute the chosen command
        if self.current_command:
            self.current_command.execute(self.robot, self.arena)

    def _evaluate_strategy(self):
        """Evaluate performance and adapt strategy"""
        if not self.robot.is_alive:
            return

        # Calculate performance score
        total_damage_dealt = 0
        total_damage_taken = 0
        objectives_completed = 0
        teammates_saved = 0

        # Gather stats from robot's memory
        for key, value in self.robot.memory.items():
            if key.startswith("damage_dealt_"):
                total_damage_dealt += value
