@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def distance_to(self, other: 'Vector2D') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def normalize(self) -> 'Vector2D':
        magnitude = math.sqrt(self.x**2 + self.y**2)
        if magnitude == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / magnitude, self.y / magnitude)

    def __add__(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other: 'Vector2D') -> 'Vector2D':
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar: float) -> 'Vector2D':
        return Vector2D(self.x * scalar, self.y * scalar)

    def __repr__(self):
        return f"Vector2D({self.x:.1f}, {self.y:.1f})"

@dataclass
class Weapon:
    name: str
    type: WeaponType
    damage: float
    range: float
    cooldown: float
    ammo: int = -1  # -1 means infinite
    max_ammo: int = -1
    spread: float = 0.0  # for ranged weapons
    projectile_speed: float = 10.0
    area_effect: float = 0.0  # for explosives

    def can_fire(self, current_time: float, last_fired: float) -> bool:
        return current_time - last_fired >= self.cooldown

    def use_ammo(self) -> bool:
        if self.ammo == -1:  # Infinite ammo
            return True
        if self.ammo > 0:
            self.ammo -= 1
            return True
        return False

@dataclass
class PowerUp:
    type: str  # "health", "speed", "shield", "ammo", "damage", "stealth"
    duration: float  # seconds
    value: float  # multiplier or absolute value
    visual_effect: str = "glow"

    def apply_effect(self, robot: 'Robot'):
        if self.type == "health":
            robot.health = min(robot.max_health, robot.health + self.value)
        elif self.type == "speed":
            robot.move_speed *= self.value
            robot.speed_boost_duration = self.duration
        elif self.type == "shield":
            robot.shield = min(robot.max_shield, robot.shield + self.value)
        elif self.type == "ammo":
            for weapon in robot.weapons:
                if weapon.ammo != -1:
                    weapon.ammo = min(weapon.max_ammo, weapon.ammo + int(self.value))
        elif self.type == "damage":
            for weapon in robot.weapons:
                weapon.damage *= self.value
            robot.damage_boost_duration = self.duration
        elif self.type == "stealth":
            robot.stealth = True
            robot.stealth_duration = self.duration

