# ======================
# DATA STRUCTURES
# ======================

@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def normalize(self) -> 'Position':
        # For movement direction
        magnitude = math.sqrt(self.x**2 + self.y**2)
        if magnitude == 0:
            return Position(0, 0)
        return Position(self.x / magnitude, self.y / magnitude)

    def __add__(self, other: 'Position') -> 'Position':
        return Position(self.x + other.x, self.y + other.y)

    def __sub__(self, other: 'Position') -> 'Position':
        return Position(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar: float) -> 'Position':
        return Position(self.x * scalar, self.y * scalar)

    def __eq__(self, other):
        return abs(self.x - other.x) < 0.1 and abs(self.y - other.y) < 0.1

    def to_tuple(self) -> Tuple[float, float]:
        return (self.x, self.y)

@dataclass
class Robot:
    id: str
    team: str
    position: Position
    health: float
    max_health: float
    armor: float
    velocity: Position
    weapon: Weapon
    ammo: int
    role: Role
    power_ups: Dict[PowerUpType, float]  # powerup_type -> remaining_duration
    last_shot: float
    last_healed: float
    vision_range: float
    is_alive: bool = True
    kill_count: int = 0
    assist_count: int = 0
    objective_progress: float = 0.0  # For objectives like flag capture
    strategy_memory: List[Dict] = field(default_factory=list)  # Historical data for learning

    def take_damage(self, damage: float) -> float:
        """Apply damage with armor reduction"""
        effective_damage = damage * (1 - min(self.armor / 100, 0.8))
        self.health -= effective_damage
        if self.health <= 0:
            self.is_alive = False
            self.health = 0
        return effective_damage

    def heal(self, amount: float) -> float:
        """Heal robot, capped by max_health"""
        before = self.health
        self.health = min(self.health + amount, self.max_health)
        return self.health - before

    def has_powerup(self, powerup_type: PowerUpType) -> bool:
        return powerup_type in self.power_ups and self.power_ups[powerup_type] > 0

    def get_speed_multiplier(self) -> float:
        """Calculate speed multiplier based on active power-ups"""
        multiplier = 1.0
        if self.has_powerup(PowerUpType.SPEED):
            multiplier *= POWERUPS[PowerUpType.SPEED].value
        if self.has_powerup(PowerUpType.BOOST):
            multiplier *= POWERUPS[PowerUpType.BOOST].value
        return multiplier

    def update_powerups(self, delta_time: float):
        """Update active power-ups and remove expired ones"""
        expired = []
        for powerup_type, duration in self.power_ups.items():
            self.power_ups[powerup_type] = max(0, duration - delta_time)
            if self.power_ups[powerup_type] <= 0:
                expired.append(powerup_type)

        for exp in expired:
            del self.power_ups[exp]

@dataclass
class Team:
    name: str
    color: str
    robots: List[Robot] = field(default_factory=list)
    base_position: Position = None
    flag_position: Position = None
    payload_position: Position = None
    score: int = 0
    objective_type: ObjectiveType = ObjectiveType.ELIMINATION
    objective_completed: bool = False
    objectives: Dict[str, Any] = field(default_factory=dict)  # Custom objective data

    def add_robot(self, robot: Robot):
        self.robots.append(robot)

    def get_alive_robots(self) -> List[Robot]:
        return [r for r in self.robots if r.is_alive]

    def get_total_health(self) -> float:
        return sum(r.health for r in self.robots if r.is_alive)

    def get_average_level(self) -> float:
        if not self.robots:
            return 0
        return sum(r.max_health + r.armor for r in self.robots) / len(self.robots)

@dataclass
class GameMap:
    width: int = GRID_SIZE
    height: int = GRID_SIZE
    hazards: List[Hazard] = field(default_factory=list)
    powerups: List[Dict] = field(default_factory=list)  # {position: PowerUp, spawn_time: float}
    spawn_points: List[Position] = field(default_factory=list)
    waypoints: List[Position] = field(default_factory=list)
    walls: List[Tuple[Position, Position]] = field(default_factory=list)
    base_positions: Dict[str, Position] = field(default_factory=dict)
    flag_positions: Dict[str, Position] = field(default_factory=dict)
    payload_positions: Dict[str, Position] = field(default_factory=dict)

    def is_valid_position(self, pos: Position) -> bool:
        """Check if position is within bounds and free of walls"""
        if pos.x < 0 or pos.x >= self.width or pos.y < 0 or pos.y >= self.height:
            return False

        # Check for walls (simplified collision)
        for wall_start, wall_end in self.walls:
            if self._line_intersection(pos, wall_start, wall_end):
                return False

        return True

    def _line_intersection(self, point: Position, line_start: Position, line_end: Position) -> bool:
        # Simple point-to-line distance check for wall collision
        # This is a simplified version for performance
        line_vec = line_end - line_start
        point_vec = point - line_start
        line_len = line_vec.distance_to(Position(0, 0))

        if line_len < 0.1:
            return point.distance_to(line_start) < 1.0

        # Project point onto the line
        projection = (point_vec.x * line_vec.x + point_vec.y * line_vec.y) / (line_len * line_len)
        projection = max(0, min(1, projection))

        closest = line_start + line_vec * projection
        return closest.distance_to(point) < 1.0

    def add_hazard(self, hazard_type: HazardType, position: Position):
        self.hazards.append({
            'type': hazard_type,
            'position': position,
            'radius': HAZARDS[hazard_type].radius,
            'active': True
        })

    def add_powerup(self, powerup_type: PowerUpType, position: Position):
        self.powerups.append({
            'position': position,
            'powerup': POWERUPS[powerup_type],
            'spawn_time': time.time(),
            'collected': False
        })

    def get_closest_powerup(self, position: Position) -> Optional[Dict]:
        """Return closest active powerup to position"""
        active_powerups = [p for p in self.powerups if not p['collected']]
        if not active_powerups:
            return None

        closest = min(active_powerups, key=lambda p: p['position'].distance_to(position))
        return closest

    def get_closest_hazard(self, position: Position) -> Optional[Dict]:
        """Return closest active hazard to position"""
        active_hazards = [h for h in self.hazards if h['active']]
        if not active_hazards:
            return None

        closest = min(active_hazards, key=lambda h: h['position'].distance_to(position))
        return closest

