class AIController:
    def __init__(self, robot: Robot, team: Team, game_map: GameMap, game_state: 'CyberArena'):
        self.robot = robot
        self.team = team
        self.game_map = game_map
        self.game_state = game_state
        self.target: Optional[Position] = None
        self.last_decision_time = 0
        self.behavior_tree = self._build_behavior_tree()
        self.strategy_learning = StrategyLearner(robot.id)

    def _build_behavior_tree(self):
        """Construct a behavior tree for AI decision making"""
        return [
            # Priority-based decision tree
            self._check_alive,
            self._check_objective_completion,
            self._check_low_health,
            self._check_enemy_nearby,
            self._check_powerup_nearby,
            self._check_objective_nearby,
            self._patrol,
            self._default_target
        ]

    def _check_alive(self) -> Optional[Dict]:
        """If robot is dead, do nothing"""
        if not self.robot.is_alive:
            return {"action": "dead", "reason": "Robot is dead"}
        return None

    def _check_low_health(self) -> Optional[Dict]:
        """If health is low, seek healing or retreat"""
        if self.robot.health < self.robot.max_health * 0.3:
            # Look for teammates to heal or safe zone
            teammates = [r for r in self.team.robots if r.is_alive and r != self.robot]
            if teammates:
                closest_teammate = min(teammates, key=lambda r: r.position.distance_to(self.robot.position))
                if closest_teammate.role == Role.SUPPORT:
                    self.target = closest_teammate.position
                    return {"action": "follow", "target": "teammate", "reason": "Low health"}
                elif self.robot.weapon.type == WeaponType.SUPPORT:
                    self.target = closest_teammate.position
                    return {"action": "heal", "target": "teammate", "reason": "Low health"}

            # Find power-up
            powerup = self.game_map.get_closest_powerup(self.robot.position)
            if powerup and powerup['powerup'].type == PowerUpType.HEALTH:
                self.target = powerup['position']
                return {"action": "collect", "target": "health_powerup", "reason": "Low health"}

            # Retreat to base
            if self.team.base_position:
                self.target = self.team.base_position
                return {"action": "retreat", "target": "base", "reason": "Low health"}
        return None

    def _check_enemy_nearby(self) -> Optional[Dict]:
        """Find and engage nearby enemies"""
        enemies = []
        for team in self.game_state.teams.values():
            if team.name != self.team.name:
                for enemy in team.get_alive_robots():
                    distance = self.robot.position.distance_to(enemy.position)
                    if distance < self.robot.vision_range:
                        enemies.append((enemy, distance))

        if enemies:
            closest_enemy, distance = min(enemies, key=lambda x: x[1])

            # If enemy is in range, attack
            if distance <= self.robot.weapon.range:
                self.target = closest_enemy.position
                return {"action": "attack", "target": "enemy", "reason": "Enemy in range", "enemy_id": closest_enemy.id}

            # Otherwise, move towards enemy
            self.target = closest_enemy.position
            return {"action": "attack_move", "target": "enemy", "reason": "Enemy nearby", "enemy_id": closest_enemy.id}

        return None

    def _check_powerup_nearby(self) -> Optional[Dict]:
        """Find and collect nearby power-ups"""
        powerup = self.game_map.get_closest_powerup(self.robot.position)
        if powerup and not powerup['collected']:
            distance = self.robot.position.distance_to(powerup['position'])
            if distance < self.robot.vision_range:
                # Prioritize important power-ups
                if powerup['powerup'].type in [PowerUpType.HEALTH, PowerUpType.SHIELD, PowerUpType.AMMO]:
                    self.target = powerup['position']
                    return {"action": "collect", "target": "powerup", "reason": "Important powerup nearby", "powerup_type": powerup['powerup'].type.value}

        return None

    def _check_objective_nearby(self) -> Optional[Dict]:
        """Handle team objectives"""
        if self.team.objective_type == ObjectiveType.CAPTURE_FLAG and self.team.flag_position:
            # Check if robot is near flag and can capture
            distance = self.robot.position.distance_to(self.team.flag_position)
            if distance < 10.0:
                # Capture flag
                self.target = self.team.flag_position
                return {"action": "capture", "target": "flag", "reason": "Flag nearby"}

        elif self.team.objective_type == ObjectiveType.ESCAPE_PAYLOAD and self.team.payload_position:
            # Escort payload
            # Find payload position (might be moving)
            payload_pos = self.team.payload_positions.get(self.team.name, self.team.payload_position)
            distance = self.robot.position.distance_to(payload_pos)
            if distance < 20.0:
                # Stay near payload
                self.target = payload_pos
                return {"action": "escort", "target": "payload", "reason": "Payload nearby"}

        elif self.team.objective_type == ObjectiveType.DEFEND_BASE and self.team.base_position:
            # Defend base
            distance = self.robot.position.distance_to(self.team.base_position)
            if distance < 30.0:
                self.target = self.team.base_position
                return {"action": "defend", "target": "base", "reason": "Base nearby"}

        return None

    def _patrol(self) -> Optional[Dict]:
        """Patrol around objectives or waypoints"""
        if self.team.objective_type == ObjectiveType.ELIMINATION:
            # Patrol around spawn point
            if self.team.spawn_points:
                waypoint = random.choice(self.team.spawn_points)
                distance = self.robot.position.distance_to(waypoint)
                if distance > 15.0:
                    self.target = waypoint
                    return {"action": "patrol", "target": "spawn_point", "reason": "No immediate threats"}

        # Use waypoints if available
        if self.game_map.waypoints:
            closest_waypoint = min(self.game_map.waypoints, 
                                 key=lambda w: self.robot.position.distance_to(w))
            distance = self.robot.position.distance_to(closest_waypoint)
            if distance > 5.0:
                self.target = closest_waypoint
                return {"action": "patrol", "target": "waypoint", "reason": "Patrolling route"}

        return None

    def _default_target(self) -> Optional[Dict]:
        """Default behavior: move towards enemy base or random point"""
        # Try to move toward enemy base
        for team_name, team in self.game_state.teams.items():
            if team_name != self.team.name and team.base_position:
                self.target = team.base_position
                return {"action": "advance", "target": "enemy_base", "reason": "Default behavior"}

        # Random movement
        random_x = random.uniform(0, self.game_map.width)
        random_y = random.uniform(0, self.game_map.height)
        self.target = Position(random_x, random_y)
        return {"action": "random", "target": "random_point", "reason": "No clear target"}

    def decide_action(self, delta_time: float) -> Dict:
        """Main AI decision function"""
        current_time = time.time()
        if current_time - self.last_decision_time < 0.5:  # Only update every 0.5 seconds
            return {"action": "hold", "reason": "Decision cooldown"}

        self.last_decision_time = current_time

        # Update strategy based on performance
        self.strategy_learning.update_performance(self.robot)

        # Execute behavior tree
        for decision in self.behavior_tree:
            result = decision()
            if result is not None:
                # Learn from this decision
                self.strategy_learning.add_decision(result)
                return result

        # Fallback
        return {"action": "hold", "reason": "No decision made"}

class StrategyLearner:
    """Simple reinforcement learning system for AI robots"""

    def __init__(self, robot_id: str):
        self.robot_id = robot_id
        self.decision_history = deque(maxlen=100)  # Last 100 decisions
        self.performance_scores = []  # Scores from recent matches
        self.strategy_weights = {
            "attack": 0.3,
            "defend": 0.3,
            "support": 0.2,
            "collect": 0.1,
            "patrol": 0.1
        }
        self.learning_rate = 0.1

    def update_performance(self, robot: Robot):
        """Update strategy based on robot performance"""
        if robot.kill_count > 0 or robot.assist_count > 0:
            score = robot.kill_count + robot.assist_count * 0.5
            self.performance_scores.append(score)

            # Maintain only last 10 scores
            if len(self.performance_scores) > 10:
                self.performance_scores.pop(0)

    def add_decision(self, decision: Dict):
        """Add decision to history and adjust weights"""
        action = decision.get("action", "unknown")
        if action in self.strategy_weights:
            # Simple reinforcement: increase weight for successful actions
            success = decision.get("reason", "") in ["Enemy in range", "Flag nearby", "Important powerup nearby"]
            if success:
                self.strategy_weights[action] = min(1.0, self.strategy_weights[action] + self.learning_rate)
            else:
                self.strategy_weights[action] = max(0.0, self.strategy_weights[action] - self.learning_rate * 0.5)

            # Normalize weights
            total = sum(self.strategy_weights.values())
            if total > 0:
                for key in self.strategy_weights:
                    self.strategy_weights[key] /= total

        self.decision_history.append(decision)

    def get_optimal_strategy(self) -> Dict:
        """Return the most effective strategy based on history"""
        if not self.performance_scores:
            return self.strategy_weights.copy()

        avg_performance = sum(self.performance_scores) / len(self.performance_scores)

        # Adjust weights based on performance
        if avg_performance > 5:  # High performance
            self.strategy_weights["attack"] = min(1.0, self.strategy_weights["attack"] + 0.1)
            self.strategy_weights["defend"] = max(0.0, self.strategy_weights["defend"] - 0.05)
        elif avg_performance < 2:  # Low performance
            self.strategy_weights["defend"] = min(1.0, self.strategy_weights["defend"] + 0.1)
            self.strategy_weights["attack"] = max(0.0, self.strategy_weights["attack"] - 0.05)

        return self.strategy_weights.copy()

