class CyberArena:
    """Main game system for CyberArena"""

    def __init__(self):
        self.teams: Dict[str, Team] = {}
        self.game_map: GameMap = GameMap()
        self.robots: Dict[str, Robot] = {}  # All robots by ID
        self.game_state: str = "idle"  # idle, running, paused, finished
        self.start_time: float = 0
        self.current_time: float = 0
        self.delta_time: float = 0
        self.last_update: float = 0

        # Game state tracking
        self.powerup_spawn_timer = 0
        self.hazard_spawn_timer = 0
        self.objective_timer = 0
        self.last_score_update = 0
        self.sound_effects = []
        self.particles = []

        # Adaptive difficulty
        self.difficulty_level = 1.0
        self.performance_history = deque(maxlen=20)  # Last 20 match performances
        self.match_count = 0

        # Initialize map
        self._initialize_map()

        # Create teams
        self._create_teams()

        # Create robots
        self._create_robots()

    def _initialize_map(self):
        """Initialize the game map with spawn points, walls, and hazards"""
        # Define spawn points for each team
        team_colors = ["red", "blue", "green", "yellow"]
        for i, team_name in enumerate(team_colors[:MAX_TEAMS]):
            # Distribute spawn points around the map
            angle = (2 * math.pi * i) / MAX_TEAMS
            x = GRID_SIZE // 2 + (GRID_SIZE // 3) * math.cos(angle)
            y = GRID_SIZE // 2 + (GRID_SIZE // 3) * math.sin(angle)
            spawn_point = Position(x, y)
            self.game_map.spawn_points.append(spawn_point)
            self.game_map.base_positions[team_name] = spawn_point

            # Add flag points for capture objectives
            flag_x = GRID_SIZE // 2 + (GRID_SIZE // 3) * math.cos(angle + math.pi)
            flag_y = GRID_SIZE // 2 + (GRID_SIZE // 3) * math.sin(angle + math.pi)
            self.game_map.flag_positions[team_name] = Position(flag_x, flag_y)

        # Add some walls for cover
        wall_count = random.randint(3, 8)
        for _ in range(wall_count):
            x1 = random.randint(10, GRID_SIZE - 10)
            y1 = random.randint(10, GRID_SIZE - 10)
            x2 = x1 + random.randint(-20, 20)
            y2 = y1 + random.randint(-20, 20)
            self.game_map.walls.append((Position(x1, y1), Position(x2, y2)))

        # Add waypoints for pathfinding
        for _ in range(15):
            x = random.randint(15, GRID_SIZE - 15)
            y = random.randint(15, GRID_SIZE - 15)
            self.game_map.waypoints.append(Position(x, y))

        # Add initial hazards
        for _ in range(3):
            hazard_type = random.choice(list(HazardType))
            x = random.randint(10, GRID_SIZE - 10)
            y = random.randint(10, GRID_SIZE - 10)
            self.game_map.add_hazard(hazard_type, Position(x, y))

        # Add initial power-ups
        for _ in range(5):
            powerup_type = random.choice(list(PowerUpType))
            x = random.randint(10, GRID_SIZE - 10)
            y = random.randint(10, GRID_SIZE - 10)
            self.game_map.add_powerup(powerup_type, Position(x, y))

    def _create_teams(self):
        """Create teams with randomized objectives"""
        team_colors = ["red", "blue", "green", "yellow"]
        objective_types = [ObjectiveType.CAPTURE_FLAG, ObjectiveType.DEFEND_BASE, 
                          ObjectiveType.ESCORTR_PAYLOAD, ObjectiveType.ELIMINATION]

        for i, color in enumerate(team_colors[:MAX_TEAMS]):
            team_name = color
            base_pos = self.game_map.base_positions[team_name]
            flag_pos = self.game_map.flag_positions[team_name]

            # Randomly assign objective (simplified)
            objective_type = objective_types[i % len(objective_types)]

            team = Team(
                name=team_name,
                color=color,
                base_position=base_pos,
                flag_position=flag_pos,
                objective_type=objective_type
            )

            # Set custom objective data
            if objective_type == ObjectiveType.ESCORTR_PAYLOAD:
                team.payload_position = Position(GRID_SIZE // 2, GRID_SIZE // 2)
                team.objectives["payload_speed"] = 0.5
                team.objectives["payload_target"] = Position(random.randint(10, GRID_SIZE-10), random.randint(10, GRID_SIZE-10))

            self.teams[team_name] = team

    def _create_robots(self):
        """Create robots for each team"""
        for team_name, team in self.teams.items():
            # Create robots for this team
            robot_count = random.randint(2, MAX_ROBOTS_PER_TEAM)
            for i in range(robot_count):
                # Assign roles based on team needs
                role = random.choice(list(Role))

                # Random weapon selection based on role
                if role == Role.ATTACKER:
                    weapon_keys = ["plasma_rifle", "railgun", "grenade"]
                elif role == Role.DEFENDER:
                    weapon_keys = ["pulse_sword", "plasma_rifle", "grenade"]
                elif role == Role.SUPPORT:
                    weapon_keys = ["heal_beam"]
                else:  # SCOUT
                    weapon_keys = ["plasma_rifle", "railgun"]

                weapon_name = random.choice(weapon_keys)
                weapon = WEAPONS[weapon_name]

                # Random starting position near team base
                base_pos = team.base_position
                offset_x = random.uniform(-5, 5)
                offset_y = random.uniform(-5, 5)
                position = Position(base_pos.x + offset_x, base_pos.y + offset_y)

                # Create robot
                robot_id = f"{team_name}_{i + 1}"
                robot = Robot(
                    id=robot_id,
                    team=team_name,
                    position=position,
                    health=100.0,
                    max_health=100.0,
                    armor=10.0,
                    velocity=Position(0, 0),
                    weapon=weapon,
                    ammo=weapon.ammo if weapon.ammo > 0 else -1,
                    role=role,
                    power_ups={},
                    last_shot=0,
                    last_healed=0,
                    vision_range=40.0,
                    kill_count=0,
                    assist_count=0
                )

                team.add_robot(robot)
                self.robots[robot_id] = robot

    def start_game(self):
        """Start the game"""
        self.game_state = "running"
        self.start_time = time.time()
        self.last_update = self.start_time
        self.current_time = 0
        print("🎮 CyberArena Game Started!")

    def update(self, dt: float):
        """Main game update loop"""
        if self.game_state != "running":
            return

        self.delta_time = dt
        self.current_time = time.time() - self.start_time

        # Update time-based systems
        self.powerup_spawn_timer += dt
        self.hazard_spawn_timer += dt
        self.objective_timer += dt

        # Spawn power-ups if needed
        if self.powerup_spawn_timer >= POWERUP_SPAWN_INTERVAL:
            self._spawn_powerup()
            self.powerup_spawn_timer = 0

        # Spawn hazards if needed
        if self.hazard_spawn_timer >= HAZARD_SPAWN_INTERVAL:
            self._spawn_hazard()
            self.hazard_spawn_timer = 0

        # Update robots and AI
        self._update_robots()

        # Update team objectives
        self._update_objectives()

        # Update adaptive difficulty
        self._update_adaptive_difficulty()

        # Update visual/audio effects
        self._update_effects()

        # Check if game is over
        self._check_game_over()

    def _spawn_powerup(self):
        """Spawn a random power-up at a random position"""
        powerup_type = random.choice(list(PowerUpType))

        # Find a valid position (not on walls)
        attempts = 0
        while attempts < 10:
            x = random.randint(5, self.game_map.width - 5)
            y = random.randint(5, self.game_map.height - 5)
