        self.expenses[category] += amount
        return True

    def set_budget_limit(self, category: BudgetCategory, limit: float) -> bool:
        if limit < 0:
            return False
        self.budget_limit[category] = limit
        return True

    def get_total_expenses(self) -> float:
        return sum(self.expenses.values())

    def get_total_budget(self) -> float:
        return sum(self.budget_limit.values())

    def get_category_spending(self, category: BudgetCategory) -> float:
        return self.expenses[category]

    def get_category_budget(self, category: BudgetCategory) -> float:
        return self.budget_limit[category]

    def is_over_budget(self, category: BudgetCategory) -> bool:
        return self.expenses[category] > self.budget_limit[category]

    def get_remaining_budget(self, category: BudgetCategory) -> float:
        return max(0, self.budget_limit[category] - self.expenses[category])

