# Game constants
SCREEN_WIDTH, SCREEN_HEIGHT = 1200, 800
FPS = 60
TEAM_COUNT = 2
MAX_ROBOTS_PER_TEAM = 5
MAX_ROBOTS = TEAM_COUNT * MAX_ROBOTS_PER_TEAM

# Team colors
TEAM_COLORS = {
    0: (0, 128, 255),  # Blue
