}

# Weapon types
class WeaponType(Enum):
    RANGED = "ranged"
    MELEE = "melee"
    SUPPORT = "support"

# Objective types
class ObjectiveType(Enum):
    FLAG_CAPTURE = "flag_capture"
    BASE_DEFENSE = "base_defense"
    PAYLOAD_ESCORT = "payload_escort"

# Robot roles
class Role(Enum):
    ATTACKER = "attacker"
    DEFENDER = "defender"
