@dataclass
class Vector2D:
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def length(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        length = self.length()
        if length == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / length, self.y / length)

    def distance_to(self, other):
        return (self - other).length()

    def to_tuple(self):
        return (int(self.x), int(self.y))

@dataclass
class Robot:
    id: int
    team: int
    position: Vector2D
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    health: float = 100.0
    max_health: float = 100.0
    armor: float = 0.0
    speed: float = 3.0
    role: Role = Role.ATTACKER
    weapon: Optional['Weapon'] = None
    cooldown: float = 0.0
    power_ups: Dict[PowerUpType, float] = field(default_factory=dict)
    last_seen_enemies: List[int] = field(default_factory=list)
    objective_progress: float = 0.0
    is_alive: bool = True
    strategy_memory: List[Dict] = field(default_factory=list)
    ai_state: str = "idle"
    ai_watcher: Optional['AIWatcher'] = None

    def __post_init__(self):
        if self.weapon is None:
            self.weapon = Weapon(WeaponType.RANGED, 25, 1.5, 100)

    def update(self, dt: float, environment: 'Environment'):
        """Update robot state each frame"""
        if not self.is_alive:
            return

        # Update cooldowns
        if self.cooldown > 0:
            self.cooldown -= dt

        # Update power-ups
        for power_type, duration in list(self.power_ups.items()):
            self.power_ups[power_type] = duration - dt
            if self.power_ups[power_type] <= 0:
                self.apply_power_up_effect(power_type, remove=True)
                del self.power_ups[power_type]

        # Apply speed multiplier from power-ups
        speed_multiplier = 1.0
        if PowerUpType.SPEED_BOOST in self.power_ups:
            speed_multiplier += 0.5

        # AI decision making
        if self.ai_watcher:
            self.ai_watcher.decide_action(self, environment)

        # Update position based on velocity
        self.position += self.velocity * dt * self.speed * speed_multiplier

        # Boundary checking
        self.position.x = max(20, min(SCREEN_WIDTH - 20, self.position.x))
        self.position.y = max(20, min(SCREEN_HEIGHT - 20, self.position.y))

        # Check for collisions with hazards
        for hazard in environment.hazards:
            if hazard.distance_to(self.position) < 30:
                self.take_damage(hazard.damage * dt, None)
                if hazard.type == HazardType.MINEFIELD:
                    self.velocity *= 0.7  # Slow down in minefield

    def take_damage(self, damage: float, attacker: Optional['Robot']):
        """Apply damage to robot"""
        actual_damage = damage * (1 - min(self.armor / 100, 0.8))
        self.health -= actual_damage
        if self.health <= 0:
            self.health = 0
            self.is_alive = False
            self.velocity = Vector2D(0, 0)
            if attacker and attacker.team != self.team:
                attacker.ai_watcher.add_kill()

    def heal(self, amount: float):
        """Heal robot"""
        self.health = min(self.max_health, self.health + amount)

    def apply_power_up_effect(self, power_type: PowerUpType, remove: bool = False):
        """Apply or remove power-up effects"""
        if power_type == PowerUpType.SPEED_BOOST:
            if remove:
                self.speed = 3.0
            else:
                self.speed = 4.5
        elif power_type == PowerUpType.SHIELD:
            if remove:
                self.armor = 0.0
            else:
                self.armor = 50.0
        elif power_type == PowerUpType.OVERLOAD:
            if remove:
                self.weapon.damage = self.weapon.base_damage
                self.weapon.fire_rate = self.weapon.base_fire_rate
            else:
                self.weapon.damage *= 2.0
                self.weapon.fire_rate *= 1.5
        elif power_type == PowerUpType.REGEN:
            if remove:
                self.health_regen_rate = 0
            else:
                self.health_regen_rate = 5.0  # per second
        elif power_type == PowerUpType.TELEPORT:
            if remove:
                pass  # Teleport is a one-time effect
            else:
                # Teleport to random location (one-time use)
                self.position = Vector2D(
                    random.randint(100, SCREEN_WIDTH - 100),
                    random.randint(100, SCREEN_HEIGHT - 100)
                )

    def fire_weapon(self, target: Vector2D, environment: 'Environment') -> bool:
        """Fire weapon at target location"""
        if self.cooldown > 0 or not self.is_alive:
            return False

        success = self.weapon.fire(self.position, target, self.team, environment)
        if success:
            self.cooldown = self.weapon.fire_rate
            return True
        return False

    def melee_attack(self, target: 'Robot') -> bool:
        """Perform melee attack on target robot"""
        if self.cooldown > 0 or not self.is_alive:
            return False

        distance = self.position.distance_to(target.position)
        if distance < self.weapon.range and target.is_alive:
            target.take_damage(self.weapon.damage * 2, self)  # Melee does extra damage
            self.cooldown = self.weapon.fire_rate
            return True
        return False

    def get_closest_enemy(self, robots: List['Robot']) -> Optional['Robot']:
        """Find closest enemy robot"""
        enemies = [r for r in robots if r.team != self.team and r.is_alive]
        if not enemies:
            return None
        return min(enemies, key=lambda e: self.position.distance_to(e.position))

    def get_closest_objective(self, environment: 'Environment') -> Optional[Vector2D]:
        """Find closest objective point"""
        if environment.objective_type == ObjectiveType.FLAG_CAPTURE:
            flag_pos = environment.flag_positions.get(self.team)
            if flag_pos:
                return flag_pos
        elif environment.objective_type == ObjectiveType.BASE_DEFENSE:
            base_pos = environment.base_positions.get(self.team)
            if base_pos:
                return base_pos
        elif environment.objective_type == ObjectiveType.PAYLOAD_ESCORT:
            if environment.payload_position:
                return environment.payload_position
        return None

    def get_team_members(self, robots: List['Robot']) -> List['Robot']:
        """Get all teammates"""
        return [r for r in robots if r.team == self.team and r.is_alive]

    def get_team_objective_progress(self, environment: 'Environment') -> float:
        """Get team's progress on current objective"""
        team_members = self.get_team_members(environment.robots)
        return sum(m.objective_progress for m in team_members) / len(team_members) if team_members else 0.0

