@dataclass
class Projectile:
    position: Vector2D
    direction: Vector2D
    damage: float
    max_range: float
    team: int
    range_traveled: float = 0.0
    alive: bool = True

    def update(self, dt: float, environment: 'Environment'):
        """Update projectile position"""
        if not self.alive:
            return

        self.position += self.direction * 15 * dt  # Fast speed
        self.range_traveled += 15 * dt

        # Check if out of range
        if self.range_traveled >= self.max_range:
            self.alive = False
            return

        # Check for collisions with robots
        for robot in environment.robots:
            if robot.is_alive and robot.team != self.team:
                if self.position.distance_to(robot.position) < 20:
                    robot.take_damage(self.damage, None)
                    self.alive = False
                    break

        # Check for collisions with walls
        if (self.position.x < 10 or self.position.x > SCREEN_WIDTH - 10 or
            self.position.y < 10 or self.position.y > SCREEN_HEIGHT - 10):
            self.alive = False

@dataclass
class PowerUp:
    position: Vector2D
    type: PowerUpType
    duration: float = 10.0
    active: bool = True

    def apply(self, robot: Robot):
        """Apply power-up to robot"""
        robot.power_ups[self.type] = self.duration
        self.active = False

@dataclass
class Hazard:
