@dataclass
class AIWatcher:
    team: int
    performance_history: List[float] = field(default_factory=list)
    difficulty_level: float = 0.5  # 0.0 = easy, 1.0 = hard
    learning_rate: float = 0.1
    strategy_memory: List[Dict] = field(default_factory=list)
    kills: int = 0
    objectives_completed: int = 0
    total_battles: int = 0

    def decide_action(self, robot: Robot, environment: Environment):
        """AI decision-making logic"""
        if not robot.is_alive:
            return

        # Determine current state
        closest_enemy = robot.get_closest_enemy(environment.robots)
        closest_objective = robot.get_closest_objective(environment)
        teammates = robot.get_team_members(environment.robots)

        # Get team objective progress
        team_progress = robot.get_team_objective_progress(environment)

        # Adaptive strategy based on difficulty and performance
        if self.performance_history:
            avg_performance = sum(self.performance_history[-5:]) / len(self.performance_history[-5:])
            if avg_performance < 0.4:
                self.difficulty_level = max(0.1, self.difficulty_level - 0.05)
            elif avg_performance > 0.7:
                self.difficulty_level = min(1.0, self.difficulty_level + 0.05)

        # Strategy selection based on role and situation
        if robot.role == Role.SCATTER:
            # Spread out to cover more area
            if closest_enemy:
                # Avoid enemy
                avoid_direction = (robot.position - closest_enemy.position).normalize()
                robot.velocity = avoid_direction * robot.speed
            else:
                # Move toward objective
                if closest_objective:
                    move_direction = (closest_objective - robot.position).normalize()
                    robot.velocity = move_direction * robot.speed
                else:
                    # Wander randomly
                    robot.velocity = Vector2D(
                        random.uniform(-1, 1),
                        random.uniform(-1, 1)
                    ).normalize() * robot.speed

        elif robot.role == Role.ATTACKER:
            # Aggressive attacker
            if closest_enemy and robot.position.distance_to(closest_enemy.position) < 150:
                # Try to engage
                if (robot.weapon.type == WeaponType.MELEE and 
                    robot.position.distance_to(closest_enemy.position) < 50):
                    # Melee attack
                    robot.melee_attack(closest_enemy)
                else:
                    # Ranged attack
                    robot.fire_weapon(closest_enemy.position, environment)

                robot.velocity = Vector2D(0, 0)
            elif closest_objective:
                # Move toward objective
                move_direction = (closest_objective - robot.position).normalize()
                robot.velocity = move_direction * robot.speed
            elif teammates:
                # Support teammates
                teammate = max(teammates, key=lambda t: t.health / t.max_health)
                move_direction = (teammate.position - robot.position).normalize()
                robot.velocity = move_direction * robot.speed * 0.8

        elif robot.role == Role.DEFENDER:
            # Defensive role
            if robot.get_closest_objective(environment):
                objective = robot.get_closest_objective(environment)
                if objective:
                    # Stay near objective
                    move_direction = (objective - robot.position).normalize()
                    robot.velocity = move_direction * robot.speed * 0.7
                    if robot.position.distance_to(objective) < 70:
                        # Patrol around objective
                        robot.velocity = Vector2D(
                            math.sin(robot.id + environment.time_elapsed) * 1.5,
                            math.cos(robot.id + environment.time_elapsed) * 1.5
                        )
            else:
                # Find and defend base
                if environment.base_positions:
                    base = environment.base_positions.get(robot.team)
                    if base:
                        move_direction = (base - robot.position).normalize()
                        robot.velocity = move_direction * robot.speed * 0.9

        elif robot.role == Role.SUPPORT:
            # Support role - heal or provide cover
            if closest_enemy and robot.position.distance_to(closest_enemy.position) < 120:
                # Create cover for teammates
                robot.velocity = Vector2D(0, 0)
                # Use weapon for suppression
                robot.fire_weapon(closest_enemy.position, environment)
            else:
                # Find low-health teammate
                vulnerable_teammate = min(
                    [t for t in teammates if t.health < t.max_health * 0.5],
                    key=lambda t: t.health,
                    default=None
                )
                if vulnerable_teammate:
                    move_direction = (vulnerable_teammate.position - robot.position).normalize()
                    robot.velocity = move_direction * robot.speed * 0.8
                else:
                    # Move toward power-up
                    if environment.power_ups:
                        closest_powerup = min(
                            environment.power_ups,
                            key=lambda p: robot.position.distance_to(p.position)
                        )
                        move_direction = (closest_powerup.position - robot.position).normalize()
                        robot.velocity = move_direction * robot.speed * 0.7

        # Ensure robot doesn't get stuck
        if robot.velocity.length() < 0.1:
            robot.velocity = Vector2D(
                random.uniform(-1, 1),
                random.uniform(-1, 1)
            ).normalize() * robot.speed * 0.5

    def add_kill(self):
        """Record a kill for performance tracking"""
        self.kills += 1

    def record_objective_completion(self):
        """Record objective completion"""
        self.objectives_completed += 1

    def record_battle(self, team_won: bool, score: float):
        """Record battle result for learning"""
        self.total_battles += 1
        self.performance_history.append(score)

        # Learn from experience
        if len(self.performance_history) > 10:
            # Remove oldest data
            self.performance_history.pop(0)

        # Update strategy based on performance
        if team_won:
            # Reinforce successful strategies
            self.strategy_memory.append({
                'difficulty': self.difficulty_level,
                'performance': score,
                'timestamp': time.time()
            })

        # Limit memory size
        if len(self.strategy_memory) > 50:
            self.strategy_memory.pop(0)


