@dataclass
class PowerUp:
    position: Position
    type: PowerUpType
    duration: float = 10.0  # seconds
    active: bool = True

    def apply(self, robot: Robot) -> None:
        """Apply power-up effect to robot"""
        if self.type == PowerUpType.HEALTH:
            robot.heal(robot.max_health * 0.5)
        elif self.type == PowerUpType.AMMO:
            robot.weapon.ammo = robot.weapon.max_ammo
        elif self.type == PowerUpType.SPEED:
            robot.speed *= 1.5
            robot.abilities["speed_boost"] = self.duration
        elif self.type == PowerUpType.SHIELD:
            robot.armor += 30
            robot.abilities["shield"] = self.duration
        elif self.type == PowerUpType.TELEPORT:
            robot.abilities["teleport"] = 0  # Make available immediately
        elif self.type == PowerUpType.CLONE:
            # Create a clone robot (simplified)
            pass
        elif self.type == PowerUpType.BOOST:
            robot.speed *= 2.0
            robot.abilities["boost"] = self.duration

        self.active = False

