    round_start_time: float = 0.0
    winner: Optional[str] = None
    last_update: float = 0.0
    bot_learning_data: Dict = None

    def __post_init__(self):
        if self.robots is None:
            self.robots = []
        if self.power_ups is None:
            self.power_ups = []
        if self.hazards is None:
            self.hazards = []
        if self.projectiles is None:
            self.projectiles = []
        if self.obstacles is None:
            self.obstacles = []
        if self.team_scores is None:
